head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");

//신청자 정보 조회 하는 팝업 
scwin.vScrenID = "ULDINS93600.xml";
scwin.param1 = "";
scwin.param2 = "";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
/********************************************** 
 * 함수명   : ins_search
 * 설명       : 신청자 정보 조회 하는 
 ***********************************************/
scwin.ins_search = function() {
    var queryId = "";
    // 신청자 정보 조회 하는 
    // param1 => STD_CD_APPL_ID , ISUR_APPL_ID
    queryId = "lds.ins.common.select.listApctInfoInquiry";
    //alert(queryId); 
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral" + "&outputMessageId=STDCDTEMP_LIST_OUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=" + queryId + "&{P}param01=" + scwin.param1 + "&{P}param02=" + scwin.param2 + "&{P}param03=" + scwin.param1 + "&{P}param04=" + scwin.param2;
    dts_List.DataID = encodeURI(url);
    dts_List.reset();
};
scwin.gform_onload = function() {
    var arrPar = new Array();
    var parentWin = $c.frame.path("../");
    var fn_GetPar = parentWin.fn_GetParam;
    if (fn_GetPar != undefined) {
        fn_GetPar(arrPar);
        scwin.param1 = ((arrPar.length >= 1) && (arrPar[0] != undefined) ? arrPar[0] : "");
        scwin.param2 = ((arrPar.length >= 1) && (arrPar[1] != undefined) ? arrPar[1] : "");
        scwin.ins_search();
    }
};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
};
scwin.btn_close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    //alert('dts_List.OnLoadCompleted('+rowcount+')');

};
